/** Share of CJK characters in a string (0 when empty). */
export function chineseRatio(text) {
    if (text === null || text === undefined || text === '')
        return 0;
    const cjk = text.match(/[\u4e00-\u9fff]/g);
    const visible = text.replace(/\s+/g, '');
    if (visible.length === 0)
        return 0;
    return (cjk === null ? 0 : cjk.length) / visible.length;
}
/** True when the text is "mostly Chinese" at the given threshold. */
export function looksChinese(text, threshold = 0.3) {
    return chineseRatio(text) >= threshold;
}
/** Clip to `max` characters, appending an ellipsis when it had to cut. */
export function truncate(text, max) {
    const clean = text.replace(/\s+/g, ' ').trim();
    if (clean.length <= max)
        return clean;
    return `${clean.slice(0, Math.max(1, max - 1))}…`;
}
/** `41234` -> `4.1 万星`; `823` -> `823 星`. */
export function starText(stars) {
    const safe = Number.isFinite(stars) && stars > 0 ? Math.round(stars) : 0;
    if (safe >= 100_000_000)
        return '破亿星';
    if (safe >= 10_000) {
        const wan = safe / 10_000;
        const rounded = wan >= 100 ? Math.round(wan) : Math.round(wan * 10) / 10;
        return `${rounded} 万星`;
    }
    if (safe >= 1_000)
        return `${(Math.round(safe / 100) / 10).toFixed(1)} 千星`;
    return `${safe} 星`;
}
/** `2024-05-01T…` -> `3 天前更新`. */
export function recencyText(pushedAt, now = Date.now()) {
    if (pushedAt === null || pushedAt === undefined || pushedAt === '')
        return '';
    const at = Date.parse(pushedAt);
    if (Number.isNaN(at))
        return '';
    const days = Math.floor((now - at) / 86_400_000);
    if (days <= 0)
        return '今天有更新';
    if (days === 1)
        return '昨天更新';
    if (days < 30)
        return `${days} 天前更新`;
    if (days < 365)
        return `${Math.floor(days / 30)} 个月前更新`;
    const years = Math.floor(days / 365);
    return years <= 1 ? '一年前更新' : `${years} 年前更新`;
}
/** Map up to `max` topics to Chinese, dropping unknown ones. */
export function zhTopics(topics, max = 2) {
    const out = [];
    if (!Array.isArray(topics))
        return out;
    for (const raw of topics) {
        if (typeof raw !== 'string')
            continue;
        const key = raw.trim().toLowerCase();
        const zh = TOPIC_ZH[key];
        if (zh === undefined)
            continue;
        if (out.includes(zh))
            continue;
        out.push(zh);
        if (out.length >= max)
            break;
    }
    return out;
}
/** Chinese name for a language, falling back to the raw name. */
export function zhLanguage(language) {
    if (language === null || language === undefined || language === '')
        return '';
    return LANG_ZH[language] ?? language;
}
/**
 * The L1 one-liner.
 *
 * Priority: a description that is already Chinese wins (it is the most
 * informative line we have). Otherwise build a structured line from topics,
 * language, stars and recency — never `undefined`, never empty.
 */
export function templateSummary(repo, now = Date.now()) {
    const description = typeof repo.description === 'string' ? repo.description : '';
    if (looksChinese(description, 0.3))
        return truncate(description, 60);
    const parts = [];
    const tags = zhTopics(repo.topics, 2);
    const language = zhLanguage(repo.language);
    if (tags.length > 0) {
        parts.push(tags.join('、'));
        if (language !== '')
            parts.push(`${language} 项目`);
    }
    else if (language !== '') {
        parts.push(`一个用 ${language} 写的开源项目`);
    }
    else {
        parts.push('一个开源项目');
    }
    parts.push(starText(repo.stargazers_count ?? 0));
    const fresh = recencyText(repo.pushed_at, now);
    if (fresh !== '')
        parts.push(fresh);
    return parts.join(' · ');
}
/** The 「为什么推荐」 line. */
export function whyText(kind, subject = '') {
    const clean = truncate(subject, 24);
    switch (kind) {
        case 'trending':
            return '近期热门：关注度高、最近还在更新';
        case 'error':
            return clean === ''
                ? '因为你在会话里遇到了报错'
                : `因为你在会话里遇到了「${clean}」这类问题`;
        case 'keyword':
            return clean === ''
                ? '因为和你正在做的事相关'
                : `因为你在会话里提到「${clean}」`;
        case 'language':
            return clean === ''
                ? '因为你常用的语言和它一致'
                : `因为你最近在用 ${clean}`;
        default:
            return '和你正在做的事相关';
    }
}
